class Solution {
public:
    int longestBalanced(string s) {
        int n = s.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int freq[26] = {0};
            int distinct = 0;
            int maxF = 0;
            for (int j = i; j < n; j++) {
                int idx = s[j] - 'a';
                if (freq[idx] == 0) distinct++;
                freq[idx]++;
                if (freq[idx] > maxF) maxF = freq[idx];
                int len = j - i + 1;
                if (maxF * distinct == len && len > ans) {
                    ans = len;
                }
            }
        }
        return ans;
    }
};
